<?php
declare(strict_types=1);
namespace Morshed\Http;
use Morshed\Core\{Database,Audit,Problem,Security,RateLimiter};
use Morshed\Product\{Membership,ConsultationCredits,PersonalProblems,Behavior,Policy,Classifications,AtlasData};
final class MembershipController
{
 private Membership $service;
 public function __construct(private Database $db,private View $view,private ?array $actor,private string $realm,private bool $api){$this->service=new Membership($db);}
 private function requireActor():array {if(!$this->actor){if(!$this->api&&($_SERVER['REQUEST_METHOD']??'GET')==='GET'){$_SESSION['return_to']=ReturnTo::current();header('Location: '.$this->view->url('/login'),true,303);exit;}throw new Problem('UNAUTHENTICATED','ابتدا وارد حساب شوید.',401);}if($this->realm==='admin')$this->service->central($this->actor);else (new Policy($this->db))->user($this->actor);$this->service->storage();return $this->actor;}
 private function present(string $title,array $data,?string $error=null):void {if($this->api){header('Content-Type: application/json; charset=utf-8');echo json_encode($data,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);}else $this->view->page($title,'membership-services',$data,$error);}
 public function get(string $path,?string $error=null):bool {
  $site=['/account/membership'=>'عضویت مجموعه‌ها','/account/credits'=>'اعتبار مشاوره من','/account/problems'=>'مسئله‌های من','/account/behavior'=>'سوابق و محدودیت‌های من','/community/manage'=>'مدیریت مجموعه و شبکه'];
  $admin=['/membership/policy'=>'سیاست‌های عضویت و مشاوره','/membership/reviews'=>'بررسی هویت و عضویت مجموعه‌ها','/membership/networks'=>'شبکه‌ها و تفویض اختیار','/membership/behavior'=>'رسیدگی به سوابق رفتاری','/membership/credits'=>'اعطای اعتبار مشاوره','/membership/reports'=>'گزارش خدمات مشاوره'];$routes=$this->realm==='admin'?$admin:$site;if(!isset($routes[$path])){if(isset($site[$path])||isset($admin[$path]))throw new Problem('ACCESS_DENIED','این صفحه در حوزهٔ حساب شما نیست.',403);return false;}$a=$this->requireActor();$uid=$a['user_id'];$central=$this->realm==='admin';$data=['screen'=>$path,'central'=>$central,'pageTitle'=>$routes[$path],'policy'=>$this->service->policy()];
  if(in_array($path,['/account/credits','/account/membership'],true))$data['balance']=(new ConsultationCredits($this->db))->balance($uid);
  if($path==='/account/credits'){$data['creditEvents']=$this->db->all('SELECT event,reason,created_at,booking_id FROM m_credit_events WHERE user_id=? ORDER BY id DESC LIMIT 100',[$uid]);$data['grants']=$this->db->all('SELECT amount,expires_at,reason FROM m_credit_grants WHERE user_id=? ORDER BY created_at DESC LIMIT 50',[$uid]);}
  if($path==='/account/membership'){$data['memberships']=$this->db->all("SELECT o.id AS org_id,o.name,'approved' AS status,COALESCE(r.relation_kind,'member') AS relation_kind,r.review_note FROM m_memberships m JOIN m_organizations o ON o.id=m.org_id LEFT JOIN m_membership_requests r ON r.org_id=m.org_id AND r.user_id=m.user_id WHERE m.user_id=? UNION ALL SELECT o.id,o.name,r.status,r.relation_kind,r.review_note FROM m_membership_requests r JOIN m_organizations o ON o.id=r.org_id WHERE r.user_id=? AND r.status<>'approved'",[$uid,$uid]);$data['organizations']=$this->service->organizations(Policy::text($_GET['q']??'',160,0));$data['myOrganizations']=$this->db->all('SELECT o.name,v.status,v.review_note FROM m_organization_verification v JOIN m_organizations o ON o.id=v.org_id WHERE v.submitted_by=? ORDER BY v.updated_at DESC LIMIT 50',[$uid]);$data['orgTypes']=(new Classifications($this->db))->types();$data['provinces']=(new AtlasData($this->db))->places();}
  if($path==='/account/problems'){$p=new PersonalProblems($this->db);$data['problems']=$p->listing($uid);$id=is_string($_GET['id']??null)?$_GET['id']:'';$data['problem']=$id?$p->get($uid,$id):[];$data['terms']=$this->db->all('SELECT id,title,kind FROM m_terms WHERE active=1 ORDER BY kind,title');$data['experiences']=$this->db->all('SELECT e.id,v.title'.AtlasData::publicBase().' ORDER BY v.title LIMIT 100');$data['memberOrganizations']=$this->db->all('SELECT o.id,o.name FROM m_memberships m JOIN m_organizations o ON o.id=m.org_id JOIN m_organization_verification v ON v.org_id=o.id AND v.status=\'approved\' WHERE m.user_id=? AND o.active=1',[$uid]);}
  if($path==='/account/behavior'){$data['behavior']=$this->db->all('SELECT id,event,status,note,review_note,booking_id,created_at FROM m_behavior_events WHERE user_id=? ORDER BY created_at DESC LIMIT 100',[$uid]);$data['restrictions']=$this->db->all('SELECT id,reason,starts_at,ends_at,revoked_at FROM m_service_restrictions WHERE user_id=? ORDER BY starts_at DESC LIMIT 50',[$uid]);}
  if(in_array($path,['/community/manage','/membership/reviews'],true)){
   $orgQuery=Policy::query(Policy::text($_GET['org_q']??'',160,0));
   $all=$central?$this->db->all('SELECT o.id,o.name,1 AS can_verify,1 AS can_members FROM m_organizations o WHERE o.name LIKE ? ORDER BY o.name LIMIT 100',[$orgQuery]):$this->db->all("SELECT o.id,o.name,MAX(d.verify_organizations) AS can_verify,MAX(d.review_members) AS can_members FROM m_organizations o JOIN m_delegations d ON d.user_id=? AND d.active=1 AND (d.verify_organizations=1 OR d.review_members=1) AND ((d.scope_kind='organization' AND d.scope_id=o.id) OR (d.scope_kind='network' AND EXISTS(SELECT 1 FROM m_network_organizations nox JOIN m_networks n ON n.id=nox.network_id AND n.active=1 WHERE nox.network_id=d.scope_id AND nox.org_id=o.id))) WHERE o.name LIKE ? GROUP BY o.id,o.name ORDER BY o.name LIMIT 100",[$uid,$orgQuery]);$allowed=array_column($all,null,'id');$this->db->run("INSERT IGNORE INTO m_organization_verification(org_id,status,contact_note,evidence,review_note,updated_at) SELECT o.id,'pending','','','',UNIX_TIMESTAMP() FROM m_organizations o");$data['scopedOrganizations']=array_values($allowed);$ids=array_keys($allowed);$data['verificationQueue']=[];$data['membershipQueue']=[];
   if($ids){$marks=implode(',',array_fill(0,count($ids),'?'));$rows=$this->db->all("SELECT v.*,o.name FROM m_organization_verification v JOIN m_organizations o ON o.id=v.org_id WHERE v.org_id IN ($marks) ORDER BY v.updated_at DESC LIMIT 100",$ids);foreach($rows as $row){if($central||!empty($allowed[$row['org_id']]['can_verify']))$data['verificationQueue'][]=$row;}
    $rows=$this->db->all("SELECT r.*,o.name,u.display_name FROM m_membership_requests r JOIN m_organizations o ON o.id=r.org_id JOIN m_users u ON u.id=r.user_id WHERE r.org_id IN ($marks) ORDER BY r.updated_at DESC LIMIT 100",$ids);foreach($rows as $row){if($central||!empty($allowed[$row['org_id']]['can_members']))$data['membershipQueue'][]=$row;}
    // Aggregate only: delegated managers never receive consultation bodies, tickets or messages.
    $data['commonIssues']=$this->db->all("SELECT t.id,t.title,COUNT(DISTINCT pp.id) AS total FROM m_personal_problems pp JOIN m_personal_problem_terms pt ON pt.problem_id=pp.id JOIN m_terms t ON t.id=pt.term_id AND t.kind='issue' WHERE pp.org_id IN ($marks) GROUP BY t.id,t.title HAVING COUNT(DISTINCT pp.user_id)>=3 ORDER BY total DESC LIMIT 20",$ids);
    $data['aggregate']=$this->db->all("SELECT o.id,o.name,COUNT(DISTINCT m.user_id) AS members,COUNT(DISTINCT CASE WHEN b.state='completed' THEN b.id END) AS completed FROM m_organizations o LEFT JOIN m_memberships m ON m.org_id=o.id LEFT JOIN m_bookings b ON b.user_id=m.user_id WHERE o.id IN ($marks) GROUP BY o.id,o.name",$ids);
   }
   $data['delegations']=$central?[]:$this->db->all('SELECT d.*,n.name AS network_name,o.name AS org_name FROM m_delegations d LEFT JOIN m_networks n ON d.scope_kind=\'network\' AND n.id=d.scope_id LEFT JOIN m_organizations o ON d.scope_kind=\'organization\' AND o.id=d.scope_id WHERE d.user_id=? AND d.active=1',[$uid]);
  }
  if($path==='/membership/networks'){$data['networks']=$this->db->all('SELECT * FROM m_networks ORDER BY name LIMIT 100');$data['organizations']=$this->service->organizations();$data['links']=$this->db->all('SELECT nox.*,n.name AS network_name,o.name AS organization_name FROM m_network_organizations nox JOIN m_networks n ON n.id=nox.network_id JOIN m_organizations o ON o.id=nox.org_id ORDER BY n.name,o.name LIMIT 200');$data['delegations']=$this->db->all('SELECT d.*,u.display_name FROM m_delegations d JOIN m_users u ON u.id=d.user_id ORDER BY d.created_at DESC LIMIT 100');$data['provinces']=(new AtlasData($this->db))->places();}
  if(in_array($path,['/membership/networks','/membership/credits','/membership/policy'],true))$data['userChoices']=$this->db->all("SELECT id,display_name FROM m_users WHERE status='active' AND display_name LIKE ? ORDER BY display_name LIMIT 50",[Policy::query(Policy::text($_GET['q']??'',160,0))]);
  if($path==='/membership/policy')$data['replyTemplates']=$this->db->all('SELECT * FROM m_consultation_replies ORDER BY code');
  if($path==='/membership/behavior'){$data['behavior']=$this->db->all('SELECT e.*,u.display_name,a.display_name AS reporter FROM m_behavior_events e JOIN m_users u ON u.id=e.user_id JOIN m_users a ON a.id=e.actor_id ORDER BY (e.status=\'reported\') DESC,e.created_at DESC LIMIT 100');$data['restrictions']=$this->db->all('SELECT r.*,u.display_name FROM m_service_restrictions r JOIN m_users u ON u.id=r.user_id ORDER BY r.starts_at DESC LIMIT 100');}
  if($path==='/membership/reports'){$data['history']=$this->db->all("SELECT action,subject_id,actor_id,before_json,after_json,created_at FROM m_knowledge_history WHERE action IN ('membership.review','organization.identity_review','membership.delegation') ORDER BY created_at DESC LIMIT 100");$data['stats']=['users'=>(int)$this->db->run("SELECT COUNT(*) FROM m_users WHERE status='active'")->fetchColumn(),'verified_organizations'=>(int)$this->db->run("SELECT COUNT(*) FROM m_organization_verification WHERE status='approved'")->fetchColumn(),'networks'=>(int)$this->db->run('SELECT COUNT(*) FROM m_networks WHERE active=1')->fetchColumn()];$data['states']=$this->db->all('SELECT state,COUNT(*) AS total FROM m_bookings GROUP BY state');$data['creditStats']=$this->db->all('SELECT state,COUNT(*) AS total FROM m_credit_reservations GROUP BY state');$data['frequentIssues']=$this->db->all('SELECT t.title,COUNT(DISTINCT b.id) AS total FROM m_personal_problem_terms pt JOIN m_terms t ON t.id=pt.term_id JOIN m_consultation_intakes i ON i.problem_id=pt.problem_id JOIN m_bookings b ON b.id=i.booking_id GROUP BY t.id,t.title ORDER BY total DESC LIMIT 20');}
  $this->present($routes[$path],$data,$error);return true;
 }
 public function post(string $path,array $d):bool {
  $site=['/account/problems/save','/account/membership/request','/account/membership/organization','/mentor/admission','/booking/reply','/booking/clarify','/behavior/report','/behavior/appeal','/community/membership/review','/community/organization/review'];$admin=['/membership/policy/save','/membership/level','/membership/credits/grant','/membership/replies/save','/membership/organization/review','/membership/member/review','/membership/network/save','/membership/network/link','/membership/delegate','/membership/behavior/review','/membership/restriction'];
  if(!in_array($path,array_merge($site,$admin),true))return false;if(!in_array($path,$this->realm==='admin'?$admin:$site,true))throw new Problem('ACCESS_DENIED','این مسیر در حوزهٔ حساب شما نیست.',403);$a=$this->requireActor();(new RateLimiter($this->db,$this->view->config['app_key']))->hit('membership-write:'.$a['user_id'],40,60);$back=$this->realm==='admin'?'/membership/reviews':'/account/membership';$id='';
  try{switch($path){
   case '/account/problems/save':$id=(new PersonalProblems($this->db))->save($a,$d);$back='/account/problems?id='.$id;break;
   case '/account/membership/request':$id=$this->service->requestMembership($a,$d);break;
   case '/account/membership/organization':$id=$this->service->proposeOrganization($a,$d);break;
   case '/mentor/admission':$this->service->saveAdmission($a,$d);$back='/mentor/calendar';break;
   case '/booking/reply':(new PersonalProblems($this->db))->reply($a,$d);$back='/booking?id='.Policy::text($d['id']??'',32);break;
   case '/booking/clarify':(new PersonalProblems($this->db))->clarify($a,$d);$back='/booking?id='.Policy::text($d['id']??'',32);break;
   case '/behavior/report':$id=(new Behavior($this->db))->report($a,$d);$back='/booking?id='.Policy::text($d['booking_id']??'',32);break;
   case '/behavior/appeal':$id=(new Behavior($this->db))->appeal($a,$d);$back='/account/behavior';break;
   case '/community/membership/review':case '/membership/member/review':$this->service->reviewMembership($a,$d);$back=$this->realm==='admin'?'/membership/reviews':'/community/manage';break;
   case '/community/organization/review':case '/membership/organization/review':$this->service->reviewOrganization($a,$d);$back=$this->realm==='admin'?'/membership/reviews':'/community/manage';break;
   case '/membership/policy/save':$this->service->savePolicy($a,$d);$back='/membership/policy';break;
   case '/membership/level':$this->service->experienceLevel($a,Policy::text($d['user_id']??'',32),Policy::integer($d['novice']??1,0,1)===1);$back='/membership/policy';break;
   case '/membership/credits/grant':$id=(new ConsultationCredits($this->db))->grant($a,$d);$back='/membership/credits';break;
   case '/membership/replies/save':$this->service->write(function()use($a,$d){$code=Policy::text($d['code']??'',24);if(!$this->db->one('SELECT code FROM m_consultation_replies WHERE code=?',[$code]))throw new Problem('NOT_FOUND','قالب پیدا نشد.',404);$this->db->run('UPDATE m_consultation_replies SET title=?,body=?,active=? WHERE code=?',[Policy::text($d['title']??'',180),Policy::text($d['body']??'',4000),Policy::integer($d['active']??0,0,1),$code]);(new Audit($this->db))->add($a['user_id'],'admin','consultation.reply_template',$code);});$back='/membership/policy';break;
   case '/membership/network/save':$id=$this->service->network($a,$d);$back='/membership/networks';break;
   case '/membership/network/link':$this->service->linkNetwork($a,Policy::text($d['network_id']??'',32),Policy::text($d['org_id']??'',32),($d['remove']??'')==='1');$back='/membership/networks';break;
   case '/membership/delegate':$this->service->delegate($a,$d);$back='/membership/networks';break;
   case '/membership/behavior/review':(new Behavior($this->db))->review($a,$d);$back='/membership/behavior';break;
   case '/membership/restriction':(new Behavior($this->db))->restriction($a,$d);$back='/membership/behavior';break;
  }}catch(Problem $e){if($this->api)throw $e;$this->view->old=$d;http_response_code($e->status);$this->view->page('اصلاح اطلاعات','classification-error',['message'=>$e->getMessage(),'input'=>$d,'retryPath'=>$path]);return true;}
  if($this->api){header('Content-Type: application/json; charset=utf-8');echo json_encode(['ok'=>true,'id'=>$id],JSON_THROW_ON_ERROR);}else{$_SESSION['flash']='اطلاعات با موفقیت ثبت شد.';header('Location: '.$this->view->url($back),true,303);}return true;
 }
}
